11. Fügen Sie eine Hauptmenü- oder Startanzeige hinzu, um das Spiel zu starten, die Spielgeschwindigkeit und andere Einstellungen zu konfigurieren.

12. Testen und überarbeiten Sie das Spiel, bis es reibungslos abläuft und alle gewünschten Features verfügbar sind.

Hier ein grober Überblick über die Struktur Ihres Codes:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <SDL2/SDL.h>

// Struktur für das Spielfeld
typedef struct {
    int width;
    int height;
    SDL_Color background_color;
    int border_width;
    SDL_Rect border_rect;
} Field;

// Struktur für die Schlange
typedef struct {
    int x, y;
    int width, height;
    int length;
    int direction;
} Snake;

// Struktur für die Frucht
typedef struct {
    int x, y;
    int width, height;
    int type;
} Fruit;

// Funktionsprototypen
void init_field(Field* field, int width, int height, SDL_Color background_color, int border_width);
void draw_field(SDL_Renderer* renderer, Field* field);
void init_snake(Snake* snake, int x, int y, int width, int height, int direction);
void draw_snake(SDL_Renderer* renderer, Snake* snake);
void move_snake(Snake* snake, int delta_x, int delta_y);
void check_snake_collision(Snake* snake, Field* field);
void init_fruit(Fruit* fruit, int x, int y, int width, int height, int type);
void draw_fruit(SDL_Renderer* renderer, Fruit* fruit);

int main(int argc, char* argv[]) {
    // Initialisierung der SDL-Engine
    SDL_Init(SDL_INIT_VIDEO);

    // Erstellen eines Fensters
    SDL_Window* window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, 800, 600, SDL_WINDOW_SHOWN);

    // Erstellen eines Renderers
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Initialisieren des Spielfelds
    Field field;
    init_field(&field, 800, 600, {0, 0, 0}, 10);

    // Initialisieren der Schlange
    Snake snake;
    init_snake(&snake, 400, 300, 10, 10, 0);

    // Initialisieren der Frucht
    Fruit fruit;
    init_fruit(&fruit, 0, 0, 10, 10, 0);

    // Spiel- und Uhr-Zeit
    int game_over = 0;
    Uint32 start_time, current_time;

    // Schleife, um das Spiel zu steuern
    while (!game_over) {
        // Warten auf eine Taste
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_KEYDOWN) {
                // Verarbeiten der Tastenbelegung
                switch (event.key.keysym.sym) {
                    case SDLK_LEFT:
                        if (snake.direction != 1) {
                            snake.direction = 2;
                        }
                        break;
                    case SDLK_RIGHT:
                        if (snake.direction != 2) {
                            snake.direction = 1;
                        }
                        break;
                    case SDLK_UP:
                        if (snake.direction != 3) {
                            snake.direction = 0;
                        }
                        break;
                    case SDLK_DOWN:
                        if (snake.direction != 0) {
                            snake.direction = 3;
                        }
                        break;
                    default:
                        break;
                }
            }
        }

        // Bewegen der Schlange
        int delta_x, delta_y;
        switch (snake.direction) {
            case 0:
                delta_y = -10;
                break;
            case 1:
                delta_x = 10;
                break;
            case 2:
                delta_x = -10;
                break;
            case 3:
                delta_y = 10;
                break;
            default:
                break;
        }
        move_snake(&snake, delta_x, delta_y);

        // Prüfen der Schlange-Kollision
        check_snake_collision(&snake, &field);

        // Bewegen der Frucht
        if (fruit.x == snake.x && fruit.y == snake.y) {
            // Erhöhen der Schlängellänge
            snake.length++;
            // Generieren einer neuen Frucht
            fruit.x = rand() % (field.width - fruit.width - 10) + 10;
            fruit.y = rand() % (field.height - fruit.height - 10) + 10;
            fruit.type = rand() % 3; // Typ der Frucht (z.B. Gelbes Obst, grüner Blatt, roter Punkt)
        }

        // Zeichnen des Spielfelds, der Schlange und der Frucht
        SDL_SetRenderDrawColor(renderer, field.background_color.r, field.background_color.g, field.background_color.b, SDL_ALPHA_OPAQUE);
        SDL_RenderClear(renderer);
        draw_field(renderer, &field);
        draw_snake(renderer, &snake);
        draw_fruit(renderer, &fruit);

        // Aktualisieren des Bildschirms
        SDL_RenderPresent(renderer);

        // Verlangsamen des Spiels
        SDL_Delay(100);

        // Prüfen, ob das Spiel vorbei ist
        if (snake.x < 0 || snake.x >= field.width - snake.width || snake.y < 0 || snake.y >= field.height - snake.height) {
            game_over = 1;
        }

        // Aktualisieren der Spiel- und Uhr-Zeit
        start_time = SDL_GetTicks();
    }

    // Beenden des Spiels
    printf("Game Over!\nScore: %d\n", snake.length);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

